INSERT INTO `carta` VALUES (1,'86c5c337-d25f-4c3e-9762-09ed0c2d36d7','33666a98-812f-4892-9f8d-33e0cbecc340','Niv-Mizzet, Parun','{U}{U}{U}{R}{R}{R}','Legendary Creature — Dragon Wizard','RU','This spell can\'t be countered.\nFlying\nWhenever you draw a card, Niv-Mizzet deals 1 damage to any target.\nWhenever a player casts an instant or sorcery spell, you draw a card.','rare','https://cards.scryfall.io/normal/front/8/6/86c5c337-d25f-4c3e-9762-09ed0c2d36d7.jpg?1783911897','2026-09-17 11:25:37'),(2,'91fdb56b-54d5-4272-8319-505ff987fe9b','6ad8011d-3471-4369-9d68-b264cc027487','Sol Ring','{1}','Artifact','','{T}: Add {C}{C}.','uncommon','https://cards.scryfall.io/normal/front/9/1/91fdb56b-54d5-4272-8319-505ff987fe9b.jpg?1783903215','2026-09-17 11:35:22'),(3,'2c747a97-9070-4c1e-b7b7-52637fbb30e1','2fda4fe7-8b0c-489c-a000-6d358e614e34','Izzet Signet','{2}','Artifact','RU','{1}, {T}: Add {U}{R}.','common','https://cards.scryfall.io/normal/front/2/c/2c747a97-9070-4c1e-b7b7-52637fbb30e1.jpg?1783907010','2026-09-17 11:50:04'),(4,'f3cc07cd-cc79-4745-b0b7-eade60175cc3','b2c6aa39-2d2a-459c-a555-fb48ba993373','Island','','Basic Land — Island','U','({T}: Add {U}.)','common','https://cards.scryfall.io/normal/front/f/3/f3cc07cd-cc79-4745-b0b7-eade60175cc3.jpg?1785981645','2026-09-17 11:52:11'),(5,'2a844b96-6616-4c39-8f4f-5d14a3b2bd55','a3fb7228-e76b-4e96-a40e-20b5fed75685','Mountain','','Basic Land — Mountain','R','({T}: Add {R}.)','common','https://cards.scryfall.io/normal/front/2/a/2a844b96-6616-4c39-8f4f-5d14a3b2bd55.jpg?1785981666','2026-09-17 11:55:37'),(6,'c6b6117c-faab-4bbb-b851-07bd8061ef03','0bc7f093-bef0-4f1a-852c-4b75ebf54838','Arcane Signet','{2}','Artifact','','{T}: Add one mana of any color in your commander\'s color identity.','uncommon','https://cards.scryfall.io/normal/front/c/6/c6b6117c-faab-4bbb-b851-07bd8061ef03.jpg?1789644435','2026-09-17 11:55:48'),(7,'ec7d6864-7b6b-4f74-8474-9b9ec96b1d33','36cd2364-d113-47d1-b2c4-b088d9eb88dd','Brainstorm','{U}','Instant','U','Draw three cards, then put two cards from your hand on top of your library in any order.','common','https://cards.scryfall.io/normal/front/e/c/ec7d6864-7b6b-4f74-8474-9b9ec96b1d33.jpg?1789599806','2026-09-23 09:25:10'),(8,'884d4eea-77c0-4b78-bb83-3f855cc77298','13cb958f-1e66-4219-901a-ff58275c8475','Brainstealer Dragon','{5}{B}{B}','Creature — Dragon Horror','B','Flying\nAt the beginning of your end step, exile the top card of each opponent\'s library. You may play those cards for as long as they remain exiled. If you cast a spell this way, you may spend mana as though it were mana of any color to cast it.\nWhenever a nonland permanent an opponent owns enters the battlefield under your control, they lose life equal to its mana value.','rare','https://cards.scryfall.io/normal/front/8/8/884d4eea-77c0-4b78-bb83-3f855cc77298.jpg?1783911933','2026-09-23 11:29:54'),(9,'7d86dc2e-6f0c-4714-9d30-5d099d3b895c','8be62f5c-0ab2-4869-97a2-d8a69a3fde95','Frodo, Sauron\'s Bane','{W}','Legendary Creature — Halfling Citizen','BW','{W/B}{W/B}: If Frodo is a Citizen, it becomes a Halfling Scout with base power and toughness 2/3 and lifelink.\n{B}{B}{B}: If Frodo is a Scout, it becomes a Halfling Rogue with \"Whenever this creature deals combat damage to a player, that player loses the game if the Ring has tempted you four or more times this game. Otherwise, the Ring tempts you.\"','rare','https://cards.scryfall.io/normal/front/7/d/7d86dc2e-6f0c-4714-9d30-5d099d3b895c.jpg?1783916334','2026-09-23 20:26:08'),(10,'83d1b37c-a8c6-4690-8701-3395397711e7','ae50be07-c8bc-45db-b47d-701c5d9ee633','Frodo, Determined Hero','{1}{W}','Legendary Creature — Halfling Warrior','W','Whenever Frodo enters or attacks, you may attach target Equipment you control with mana value 2 or 3 to Frodo.\nDuring your turn, prevent all damage that would be dealt to Frodo.','rare','https://cards.scryfall.io/normal/front/8/3/83d1b37c-a8c6-4690-8701-3395397711e7.jpg?1783916219','2026-09-23 20:56:08'),(11,'328df403-7428-4b17-bdd1-9759fc0f32d8','58ee8c10-7be8-4889-944d-13cae0a4166d','Frodo, Adventurous Hobbit','{W}{B}','Legendary Creature — Halfling Scout','BW','Partner with Sam, Loyal Attendant\nVigilance\nWhenever Frodo attacks, if you gained 3 or more life this turn, the Ring tempts you. Then if Frodo is your Ring-bearer and the Ring has tempted you two or more times this game, draw a card.','mythic','https://cards.scryfall.io/normal/front/3/2/328df403-7428-4b17-bdd1-9759fc0f32d8.jpg?1783916041','2026-09-23 20:56:44'),(12,'687a2b76-3f05-4732-bd9b-513d06d16300','2837be10-23ad-49d2-943e-b1e00edbbbd9','Sam, Loyal Attendant','{1}{G}{W}','Legendary Creature — Halfling Peasant','GW','Partner with Frodo, Adventurous Hobbit (When this creature enters, target player may put Frodo into their hand from their library, then shuffle.)\nAt the beginning of combat on your turn, create a Food token. (It\'s an artifact with \"{2}, {T}, Sacrifice this token: You gain 3 life.\")\nActivated abilities of Foods you control cost {1} less to activate.','mythic','https://cards.scryfall.io/normal/front/6/8/687a2b76-3f05-4732-bd9b-513d06d16300.jpg?1783916039','2026-09-23 20:57:19'),(13,'eb912458-e016-4ea2-a2ea-40ac1a57f8fb','5c8e5092-962e-49ef-ab82-8434e475e4e7','Food Chain','{2}{G}','Enchantment','G','Exile a creature you control: Add X mana of any one color, where X is 1 plus the exiled creature\'s mana value. Spend this mana only to cast creature spells.','mythic','https://cards.scryfall.io/normal/front/e/b/eb912458-e016-4ea2-a2ea-40ac1a57f8fb.jpg?1783921868','2026-09-23 20:57:28'),(14,'8ab0f4c0-b331-4c57-b68f-2e24bb5ba06c','bc71ebf6-2056-41f7-be35-b2e5c34afa99','Plains','','Basic Land — Plains','W','({T}: Add {W}.)','common','https://cards.scryfall.io/normal/front/8/a/8ab0f4c0-b331-4c57-b68f-2e24bb5ba06c.jpg?1785981632','2026-09-24 10:36:02'),(15,'da1ff886-d3c8-43e5-8bf0-ba4f0b259781','4c3a865a-88b1-43e0-b326-17c45670da54','Niv-Mizzet, Supreme','{W}{U}{B}{R}{G}','Legendary Creature — Dragon Avatar','BGRU